import{_ as a,o as r,c as i,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Закон о Противодействии Монополиям","description":"","frontmatter":{},"headers":[],"relativePath":"ru/47-反垄断法.md","filePath":"ru/47-反垄断法.md"}'),e={name:"ru/47-反垄断法.md"};function d(o,t,n,s,h,b){return r(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="закон-о-противодеиствии-монополиям" tabindex="-1">Закон о Противодействии Монополиям <a class="header-anchor" href="#закон-о-противодеиствии-монополиям" aria-label="Permalink to &quot;Закон о Противодействии Монополиям&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>47</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Антимонополия, Добросовестная конкуренция, Симбиотический рыночный порядок, Запрет хищнических действий, Обеспечение совместного продвижения Десяти Тысяч Рас</td></tr></tbody></table><h2 id="i-цель-законодательства-и-основные-принципы" tabindex="-1">I. Цель законодательства и основные принципы <a class="header-anchor" href="#i-цель-законодательства-и-основные-принципы" aria-label="Permalink to &quot;I. Цель законодательства и основные принципы&quot;">​</a></h2><p><em>Закон о Противодействии Монополиям</em> — один из пяти вспомогательных законов Симбиотической Цивилизации Якоря. Он направлен на предотвращение монопольных и хищнических действий в сфере культивационных ресурсов, культивационных сект, коммерческих рынков и других областях, поддержание добросовестной конкуренции и симбиотического рыночного порядка Вселенной Хэнъюань, а также обеспечение «совместного продвижения Десяти Тысяч Рас» — гарантию того, что никакая сила или организация не сможет захватить возможности развития через монополию.</p><p>Настоящий Закон устанавливает следующие основные принципы:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Добросовестная конкуренция</td><td>Все субъекты конкурируют на равных основаниях; злоупотребление доминирующим положением и недобросовестная конкуренция запрещены</td></tr><tr><td>Открытый рынок</td><td>Монопольные соглашения, раздел рынка и ограничения конкуренции, исключающие или ограничивающие конкуренцию, запрещены</td></tr><tr><td>Защита слабых</td><td>Приоритетная защита новых культиваторов, начинающих рас и малых и средних организаций</td></tr><tr><td>Симбиотический порядок</td><td>Рынок должен служить совместному продвижению Десяти Тысяч Рас; грабёж общественных интересов капиталом и властью запрещён</td></tr><tr><td>Единое правоприменение</td><td>Антимонопольное правоприменение осуществляется единым органом; местный протекционизм и межплоскостные монопольные действия запрещены</td></tr></tbody></table><h2 id="ii-определение-монополии" tabindex="-1">II. Определение монополии <a class="header-anchor" href="#ii-определение-монополии" aria-label="Permalink to &quot;II. Определение монополии&quot;">​</a></h2><p>Настоящий Закон определяет следующие действия как монопольные, которые запрещены:</p><ol><li><strong>Монопольные соглашения</strong>: соглашения между конкурентами или между предприятиями верхнего и нижнего звена о фиксации цен, разделе рынков, ограничении объёма производства, бойкоте и т.д.</li><li><strong>Злоупотребление доминирующим положением</strong>: злоупотребление доминирующим положением на рынке для продажи по неоправданно высоким ценам, продажи ниже себестоимости, навязывания необоснованных условий сделок, отказа от сделок, принудительного ассортимента и т.д.</li><li><strong>Концентрация операторов</strong>: слияния, поглощения и совместные предприятия, устраняющие или ограничивающие конкуренцию, с предварительной подачей заявления в антимонопольный орган для проверки.</li><li><strong>Административная монополия</strong>: злоупотребление административной властью государственными органами и общественными организациями для ограничения конкуренции, местный протекционизм и отраслевая монополия.</li><li><strong>Монополия культивационных ресурсов</strong>: монопольный контроль культивационных ресурсов, узлов духовной энергии и тайных миров, исключающий других из культивации.</li><li><strong>Монополия талантов</strong>: использование недобросовестных средств для исключительного контроля культивационных талантов, ограничивающее свободное перемещение талантов.</li></ol><h2 id="iii-антимонопольные-органы" tabindex="-1">III. Антимонопольные органы <a class="header-anchor" href="#iii-антимонопольные-органы" aria-label="Permalink to &quot;III. Антимонопольные органы&quot;">​</a></h2><p>Симбиотический Суд и его аффилированные антимонопольные органы осуществляют следующие функции:</p><table tabindex="0"><thead><tr><th>Орган</th><th>Функция</th></tr></thead><tbody><tr><td>Бюро антимонопольного правоприменения</td><td>Расследует монопольные действия, открывает расследования по подозрению в монополии</td></tr><tr><td>Комитет по проверке монополий</td><td>Проверяет концентрацию операторов и изменения рыночной структуры</td></tr><tr><td>Управление надзора за ценами</td><td>Надзор за ценовым поведением на важные культивационные ресурсы и товары</td></tr><tr><td>Бюро межплоскостной координации</td><td>Координирует антимонопольное правоприменение между плоскостями, предотвращая межплоскостные монополии</td></tr></tbody></table><p>Антимонопольный орган наделён следственными полномочиями: может требовать от заинтересованных лиц пояснений, проверять книги и записи, опечатывать и изымать доказательства и т.д. Проверяемые лица обязаны сотрудничать и не должны отказываться или препятствовать.</p><h2 id="iv-особые-положения-о-монополии-культивационных-ресурсов" tabindex="-1">IV. Особые положения о монополии культивационных ресурсов <a class="header-anchor" href="#iv-особые-положения-о-монополии-культивационных-ресурсов" aria-label="Permalink to &quot;IV. Особые положения о монополии культивационных ресурсов&quot;">​</a></h2><p>Культивационные ресурсы — общественное богатство Вселенной Хэнъюань; настоящий Закон устанавливает особые положения об их антимонопольной защите:</p><ol><li><strong>Равенство доступа к ресурсам</strong>: все расы и культиваторы имеют равные права доступа к культивационным ресурсам; ни одна секта или организация не может исключительно занимать ключевые ресурсы.</li><li><strong>Совместное использование узлов духовной энергии</strong>: ключевые узлы духовной энергии реализуют систему совместного управления; исключительное занятие и создание частных культивационных анклавов запрещены.</li><li><strong>Открытая система тайных миров</strong>: тайные миры, обнаруженные любым субъектом, должны быть заявлены в орган управления и войти в систему общественных ресурсов; тайное занятие запрещено.</li><li><strong>Регулирование рынка пилюль</strong>: важные пилюли и духовные лекарства реализуют ценовое ориентирование и надзор за предложением; скупка и взвинчивание цен запрещены.</li><li><strong>Надзор за обращением артефактов</strong>: обращение артефактов высокого уровня подлежит регистрации и управлению; создание вооружённой артефактной монополии путём контроля источников артефактов запрещено.</li></ol><h2 id="v-средства-правовои-защиты-и-юридическая-ответственность" tabindex="-1">V. Средства правовой защиты и юридическая ответственность <a class="header-anchor" href="#v-средства-правовои-защиты-и-юридическая-ответственность" aria-label="Permalink to &quot;V. Средства правовой защиты и юридическая ответственность&quot;">​</a></h2><p>За монопольные действия настоящий Закон предусматривает следующие средства и ответственность:</p><ul><li><strong>Предписание прекратить</strong>: антимонопольный орган предписывает прекращение монопольных действий.</li><li><strong>Штрафы</strong>: штрафы налагаются в зависимости от незаконного дохода и тяжести обстоятельств.</li><li><strong>Изъятие незаконного дохода</strong>: незаконный доход, полученный в результате монопольных действий, изымается.</li><li><strong>Лишение квалификации</strong>: при серьёзных обстоятельствах аннулируются лицензии на предпринимательскую деятельность или квалификации культивационных сект.</li><li><strong>Возмещение ущерба</strong>: потерпевшие от монопольных действий имеют право требовать возмещения ущерба.</li><li><strong>Уголовная ответственность</strong>: если монопольное действие образует состав преступления, наступает уголовная ответственность.</li></ul><h2 id="vi-публичныи-иск" tabindex="-1">VI. Публичный иск <a class="header-anchor" href="#vi-публичныи-иск" aria-label="Permalink to &quot;VI. Публичный иск&quot;">​</a></h2><p>За монопольные действия, наносящие вред общественным интересам, следующие субъекты могут подавать антимонопольный публичный иск в Симбиотический Суд:</p><ul><li>Антимонопольные органы</li><li>Симбиотические общественные организации</li><li>Иные субъекты, предусмотренные законом</li></ul><p>Публичный иск направлен на прекращение монопольных действий, защиту общественного интереса рыночного порядка и возмещение ущерба, причинённого общественным интересам.</p><h2 id="vii-деиствие-закона" tabindex="-1">VII. Действие закона <a class="header-anchor" href="#vii-деиствие-закона" aria-label="Permalink to &quot;VII. Действие закона&quot;">​</a></h2><p>Настоящий Закон применяется ко всем монопольным действиям, совершённым во Вселенной Хэнъюань, включая монопольные действия субъектов из других вселенных, находящихся в юрисдикции Вселенной Хэнъюань. К монопольным действиям, совершённым через вселенные, применяется принцип взаимности и консультаций.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Закон о Противодействии Монополиям</em> — правовой оплот философии «совместного продвижения Десяти Тысяч Рас» Симбиотической Цивилизации Якоря. Определяя и наказывая монопольные действия, создавая специальные органы и регулируя монополию культивационных ресурсов, он обеспечивает справедливость и открытость симбиотического рынка, предотвращает грабёж ресурсов и возможностей развития любой силой и предоставляет институциональные гарантии совместного продвижения Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>42-消费者保护法 (Закон о Защите Прав Потребителей)</li><li>41-共生劳动法 (Симбиотический Трудовой Закон)</li><li>07-联产承包机制详解 (Подробное описание механизма совместного подряда)</li></ul>',29)])])}const c=a(e,[["render",d]]);export{u as __pageData,c as default};
